/**
 * Text pages for language models: `/llms.txt`, `/llms-full.txt` and a few `.md` pages. They are generated by `npm run data:llms` into
 * `public/data/llms/` and published with the other data files, so the Worker reads them from the bucket (key `areas/llms/<file>`).
 */
interface Env { ASSETS: Fetcher; DATA: R2Bucket }

const MARKDOWN = "text/markdown; charset=utf-8";
const PLAIN = "text/plain; charset=utf-8";

/** Path to stored file name and content type. Nothing else is served from here. */
export const TEXT_ROUTES: Record<string, { file: string; type: string }> = {
  "/llms.txt": { file: "llms.txt", type: PLAIN },
  "/llms-full.txt": { file: "llms-full.txt", type: PLAIN },
  ...Object.fromEntries(
    ["index", "proposals", "streets", "methodology", "assumptions", "sources", "scenario-links", "data-files", "run-locally"].map((n) => [`/${n}.md`, { file: `${n}.md`, type: MARKDOWN }]),
  ),
};

export const textRoute = (pathname: string) => TEXT_ROUTES[pathname] ?? null;
/** Paths for `run_worker_first` in wrangler.jsonc. */
export const TEXT_PATHS = Object.keys(TEXT_ROUTES);

const SAFE = { "x-content-type-options": "nosniff", "cache-control": "no-cache" };

function missing(): Response {
  return new Response("Not found. This page is generated by `npm run data:llms` and published with `npm run data:push`.\n", { status: 404, headers: { ...SAFE, "content-type": PLAIN } });
}

export async function serveText(req: Request, env: Env, route: { file: string; type: string }): Promise<Response> {
  if (req.method !== "GET" && req.method !== "HEAD") {
    return new Response("Method not allowed.\n", { status: 405, headers: { ...SAFE, allow: "GET, HEAD", "content-type": PLAIN } });
  }
  const head = req.method === "HEAD";
  const object = await env.DATA.get(`areas/llms/${route.file}`, { onlyIf: req.headers });
  if (object) {
    const headers = new Headers({ ...SAFE, "content-type": route.type, etag: object.httpEtag });
    if (!("body" in object)) return new Response(null, { status: 304, headers });
    return new Response(head ? null : object.body, { headers });
  }
  // Local development has no bucket entry: the generated files sit in public/data/llms.
  const res = await env.ASSETS.fetch(new Request(new URL(`/data/llms/${route.file}`, req.url), { headers: req.headers }));
  if (res.status === 304) return new Response(null, { status: 304, headers: { ...SAFE, "content-type": route.type } });
  if (res.ok && !(res.headers.get("content-type") ?? "").includes("html")) {
    const headers = new Headers({ ...SAFE, "content-type": route.type });
    const etag = res.headers.get("etag");
    if (etag) headers.set("etag", etag);
    return new Response(head ? null : res.body, { headers });
  }
  return missing();
}
